            As a genius expert, your task is to understand the content and provide
            the parsed objects in json that match the following json_schema:


            {
  "$defs": {
    "StatementFaithfulnessAnswer": {
      "description": "Individual statement with reason and verdict for NLI evaluation.",
      "properties": {
        "statement": {
          "description": "the original statement, word-by-word",
          "title": "Statement",
          "type": "string"
        },
        "reason": {
          "description": "the reason of the verdict",
          "title": "Reason",
          "type": "string"
        },
        "verdict": {
          "description": "the verdict(0/1) of the faithfulness",
          "title": "Verdict",
          "type": "integer"
        }
      },
      "required": [
        "statement",
        "reason",
        "verdict"
      ],
      "title": "StatementFaithfulnessAnswer",
      "type": "object"
    }
  },
  "description": "Structured output for NLI statement evaluation.",
  "properties": {
    "statements": {
      "description": "Evaluated statements with verdicts",
      "items": {
        "$ref": "#/$defs/StatementFaithfulnessAnswer"
      },
      "title": "Statements",
      "type": "array"
    }
  },
  "required": [
    "statements"
  ],
  "title": "NLIStatementOutput",
  "type": "object"
}

            Make sure to return an instance of the JSON, not the schema itself

